import backtrader as bt


class BollingerMeanReversionStrategy(bt.Strategy):
    params = dict(period=20, devfactor=2.0, risk=0.015, stop_loss=0.06)

    def __init__(self):
        self.boll = bt.ind.BollingerBands(self.data.close, period=self.p.period, devfactor=self.p.devfactor)
        self.zscore = (self.data.close - self.boll.mid) / (self.boll.top - self.boll.mid)
        self.volume_ma = bt.ind.SMA(self.data.volume, period=20)
        self.order = None
        self.entry_price = None

    def position_size(self):
        cash = self.broker.getcash()
        max_risk = cash * self.p.risk
        stop_gap = max(self.data.close[0] * self.p.stop_loss, 0.01)
        return int(max_risk / stop_gap)

    def next(self):
        if self.order:
            return
        close = self.data.close[0]
        volume_ok = self.data.volume[0] > self.volume_ma[0]
        oversold = close < self.boll.bot[0]
        overbought = close > self.boll.top[0]
        mean_reversion_signal = oversold and volume_ok
        if not self.position and mean_reversion_signal:
            self.entry_price = close
            self.order = self.buy(size=self.position_size())
        elif self.position:
            take_profit = close >= self.boll.mid[0]
            stop_loss = close < self.entry_price * (1 - self.p.stop_loss)
            risk_control = stop_loss or close < self.boll.bot[0] * 0.97
            if take_profit or risk_control or overbought:
                self.order = self.sell(size=self.position.size)

    def notify_trade(self, trade):
        if trade.isclosed:
            print('pnl', trade.pnl, 'drawdown risk checked')

    def stop(self):
        print('mean reversion backtest completed with sharpe and drawdown analysis')
